// DeleteUniqueIndexCache 删除索引存在的缓存
func (c *ContractRecordRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.ContractRecord) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, c.cache.Key(CacheContractRecordByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[c.cache.Key(CacheContractRecordByIDPrefix, item.ID)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordByActivityStartDatePrefix, item.ActivityStartDate)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordByChildIDTopicActivityStartDatePrefix, item.ChildID, item.Topic, item.ActivityStartDate)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordByParentNamePrefix, item.ParentName)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordBySignFlowIDPrefix, item.SignFlowID)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordByTopicPrefix, item.Topic)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordByChildIDTopicPrefix, item.ChildID, item.Topic)] = struct{}{}
			KeyMap[c.cache.Key(CacheContractRecordByChildIDPrefix, item.ChildID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := c.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
